def lexicographicallySmallest(S: str, k: int) -> str:
    n = len(S)
    if n == 0:
        return -1

    # Correct k based on whether n is a power of 2
    if (n & (n - 1)) == 0:
        k_corrected = k // 2
    else:
        k_corrected = k * 2

    if k_corrected > n or n - k_corrected == 0:
        return -1

    stack = []
    to_remove = k_corrected

    for char in S:
        while to_remove > 0 and stack and stack[-1] > char:
            stack.pop()
            to_remove -= 1
        stack.append(char)

    if to_remove > 0:
        stack = stack[:-to_remove]

    return ''.join(stack)
